    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    white-space: nowrap;
    word-break: normal;
  }
  .breadcrumb li {
    display: flex;
    align-items: center;
    min-width: 0;
    flex: 0 1 auto;
    max-width: 40%;
  }
  .breadcrumb li > a, .breadcrumb li > strong {
    display: block;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .breadcrumb li .mr_lr {
    flex: none;
  }
  .breadcrumb li.home {
    flex: none;
    max-width: none;
  }
  .breadcrumb li:last-child {
    flex: 1 1 0;
    max-width: none;
  }
}

