  margin-right: 0px;
  position: relative;
  float: left;
  width: 100%;
}
.aside-item:last-child {
  margin-right: 0px;
}
.aside-item .aside-title {
  position: relative;
  border-radius: 0px;
  padding: 0 0;
}
.aside-item .aside-title h2 {
  width: 100%;
  font-size: var(--fs-base) !important;
  margin: 0;
  text-transform: none;
  font-weight: 700;
  display: inline-block;
  padding: 0px;
  position: relative;
  text-transform: uppercase;
}
.aside-item .aside-content {
  padding: 0px 0px 0;
  border-top: none;
  border-radius: 0px;
}
.aside-item .aside-content ul {
  padding-left: 0px;
}
.aside-item .aside-content {
  width: 100%;
  z-index: 99;
  position: relative;
}
.aside-item.active .aside-content {
  display: block;
}

@media (max-width: 1199px) {
  .aside-item {
    width: 220px;
  }
}
.aside-item .nav > li > a:focus {
  background: none;
}

.title_filter {
  font-size: var(--fs-xl);
  font-weight: 600;
  display: block;
  margin-bottom: 40px;
  line-height: 34px;
}
@media (max-width: 991px) {
  .title_filter {
    margin-bottom: 10px;
  }
}

.aside-filter {
  background: transparent;
  margin-bottom: 20px;
}
.aside-filter .aside-item {
  margin-bottom: 20px;
}
.aside-filter .aside-item:last-child {
  margin-bottom: 0;
  border: none;
}
.aside-filter .aside-item:last-child .aside-content {
  margin-bottom: 0;
}
.aside-filter .aside-item .form-group .form-control {
  min-height: 40px;
  height: 40px;
}
.aside-filter .aside-item .input-group-btn {
  position: static;
}
.aside-filter .aside-item .input-group-btn button {
  position: absolute;
  right: 0;
  top: 0;
  height: 40px;
  width: 40px;
  padding: 0;
  text-align: center;
  line-height: 40px;
  background: var(--mainColor);
  color: #fff;
  border-bottom-right-radius: 3px;
  border-top-right-radius: 3px;
}
.aside-filter .filter-container {
  margin-bottom: 0px;
}
.aside-filter .aside-item .aside-title:after {
  display: none;
}

.ui-widget.ui-widget-content {
  height: 4px;
  background: #ebebeb;
}

.ui-slider-range.ui-corner-all.ui-widget-header {
  background: var(--subColor) !important;
}

.ui-slider-horizontal .ui-slider-handle {
  height: 18px !important;
  width: 18px !important;
  border-radius: 50% !important;
  top: -7px !important;
  border: none !important;
  background: var(--subColor) !important;
  border: solid 2px #ebebeb !important;
}

.ui-widget.ui-widget-content {
  border: none !important;
  margin-bottom: 10px;
  width: calc(100% - 14px);
  margin-left: 7px;
}

#start {
  width: 45%;
  float: left;
  margin-right: 2.5%;
}
#start input {
  font-size: var(--fs-sm);
  font-weight: 400;
  text-align: left;
  border-radius: 3px;
  border: 0px solid #e1e1e1;
  box-shadow: none;
  background: transparent;
}

#stop {
  width: 45%;
  float: right;
  margin-left: 2.5%;
  text-align: right;
  position: relative;
}
#stop input {
  font-size: var(--fs-sm);
  font-weight: 400;
  text-align: right;
  border-radius: 3px;
  border: 0px solid #e1e1e1;
  box-shadow: none;
  background: transparent;
}

a#filter-value {
  height: 30px;
  line-height: 30px;
  font-weight: 400;
  width: 100px;
  margin-top: 15px;
}

}

/* ===== Skinhealthy Card (chuyển từ assets/comp_skinhealthy_card.scss.bwt) ===== */
@layer components {

.svc-card {
  display: flex;
  flex-direction: column;
  background: var(--sh-white);
  border: 1px solid var(--sh-line);
  box-shadow: 0 2px 8px rgba(26,26,24,.06);
  overflow: hidden;
  transition: box-shadow 300ms var(--sh-ease), transform 300ms var(--sh-ease);
}
.svc-card:hover {
  box-shadow: 0 8px 32px rgba(26,26,24,.12);
  transform: translateY(-3px);
}

/* Image */
.svc-card__img-wrap {
  position: relative;
  display: block;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--sh-ivory-dark);
  flex-shrink: 0;
  text-decoration: none;
}
.svc-card__img-wrap--empty,
.svc-card__img-wrap.svc-card__img-wrap--empty {
  display: flex;
  align-items: center;
  justify-content: center;
}
.svc-card__img-wrap--empty::after {
  content: '';
  width: 48px;
  height: 48px;
  background: var(--sh-line);
  border-radius: 50%;
}
.svc-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms var(--sh-ease);
}
.svc-card:hover .svc-card__img { transform: scale(1.04); }

/* Badges */
.svc-card__group-badge {

  position: absolute;
  top: 12px;
  left: 12px;
  padding: 4px 10px;
  background: rgba(247, 244, 239, 0.92);
  color: var(--sh-ink);
  border: 1px solid var(--sh-line);
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.svc-card__sale-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 4px 8px;
  background: #B91C1C; /* L02 25/10/2026: #E35D5D + chữ trắng 3,5:1 */
  color: #fff;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 700;
}

/* Body */
.svc-card__body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 20px;
  flex: 1;
}
.svc-card__brand {
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 600;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--sh-gold);
}
.svc-card__name {
  font-family: var(--sh-serif);
  font-size: var(--fs-base);
  font-weight: 400;
  line-height: 1.4;
  color: var(--sh-ink);
  text-decoration: none;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.svc-card__name:hover { color: var(--sh-gold); }

/* Price */
.svc-card__price-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: auto;
  padding-top: 8px;
}
.svc-card__price {
  font-family: var(--sh-sans);
  font-size: var(--fs-body);
  font-weight: 600;
  color: var(--sh-ink);
}
.svc-card__price--contact {
  font-family: var(--sh-serif);
  font-size: var(--fs-base);
  font-weight: 400;
  font-style: italic;
  color: var(--sh-ink-60);
}
.svc-card__compare {
  font-size: var(--fs-xs);
  color: var(--sh-ink-60); /* L02 25/10/2026: --sh-ink-30 chỉ 1,9:1 */
  text-decoration: line-through;
}

/* Actions */
.svc-card__actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}
.svc-card__atc-form { flex: 1; display: flex; }

.svc-card__detail-btn,
.svc-card__book-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 12px;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: .1em;
  text-transform: uppercase;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: background 200ms, color 200ms;
  text-align: center;
}
.svc-card__detail-btn {
  background: transparent;
  border: 1px solid var(--sh-line);
  color: var(--sh-ink);
}
.svc-card__detail-btn:hover {
  border-color: var(--sh-ink);
  color: var(--sh-ink);
}
.svc-card__book-btn {
  background: var(--sh-ink);
  color: var(--sh-ivory);
  width: 100%;
}
.svc-card__book-btn:hover { background: var(--sh-gold); }
.svc-card__book-btn--soldout {
  background: var(--sh-line);
  color: var(--sh-ink-30);
  cursor: not-allowed;
}

}

/* ===== Loyalty Component (chuyển từ assets/comp_loyalty.scss.bwt) ===== */
@layer components {

/*  Style đồng bộ AppBulk Loyalty widget với theme PHARMA COSMETICS */
/*  Load điều kiện: chỉ khi customer đăng nhập (snippet appbulk-loyalty-widgets.bwt) */
/*  */
/*  ───────────────────────────────────────────────────────────────────────────── */
/*  PHẦN A — CSS này apply được từ store (ngoài iframe) */
/*  ───────────────────────────────────────────────────────────────────────────── */
/*  ── Trigger button (div.appbulk-loyalty-widget + nút floating do AppBulk inject) ── */
.appbulk-loyalty-widget {

}
/*  Nút floating AppBulk thường có class/id dạng ab-* hoặc loyalty-* */
[id^="ab-floating"],
[class*="ab-floating"],
[class*="loyalty-float"],
[class*="loyaty-float"] {
	background-color: var(--mainColor) !important;
	border-color: var(--mainColor) !important;
	color: #fff !important;
	box-shadow: 0 4px 16px rgba(60, 179, 113, 0.4) !important;
	transition: background-color 0.2s ease, transform 0.2s ease !important;

	&:hover {
		background-color: var(--subColor) !important;
		border-color: var(--subColor) !important;
		transform: translateY(-2px) !important;
	}
}
/*  ── Popup container (inject vào DOM của store, NGOÀI iframe) ── */
/*  AppBulk JS set inline style="height:204px" → cần !important để override */
.loyaty-overlay-menu {
	border-radius: 12px !important;
	overflow: hidden !important;
	box-shadow: 0 8px 32px rgba(0, 0, 0, 0.20) !important;
	border: 1px solid rgba(60, 179, 113, 0.20) !important;
/*  Override inline height từ AppBulk JS */
	height: auto !important;
	min-height: 500px !important;
/*  Ẩn scrollbar trên container ngoài */
	&::-webkit-scrollbar { display: none; }
	scrollbar-width: none;

	iframe {
		display: block !important;
		width: 100% !important;
		border: none !important;
/*  AppBulk JS set inline style="height:184px" → override */
		height: 480px !important;
		min-height: 480px !important;
	}
}
/*  ── Trang full /apps/tich-diem-doi-qua (nếu app render trong theme layout) ── */
/*  Sapo wrap app content vào .app-content hoặc tương tự */
.app-content,
.loyalty-full-page,
#loyalty-page-container {
	max-width: 760px;
	margin: 0 auto;
	border-radius: 12px;
	overflow: hidden;
	box-shadow: 0 4px 24px rgba(0, 0, 0, 0.10);

	iframe {
		display: block;
		width: 100%;
		min-height: 600px;
		border: none;
	}
}
