  text-align: center;
}
.svcs-cta__title {
  font-family: var(--sh-serif);
  font-size: var(--fs-display);
  font-weight: 300;
  color: var(--sh-ivory);
  letter-spacing: .03em;
  margin-bottom: 12px;
}
.svcs-cta__title em { font-style: italic; }
.svcs-cta__sub {
  font-family: var(--sh-sans);
  font-size: var(--fs-xs);
  color: rgba(247,244,239,.6);
  margin-bottom: 36px;
}
.svcs-cta__btns {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}
.svcs-cta__btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 32px;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
