/* ===== Skinhealthy Home (chuyển từ assets/page_skinhealthy_home.scss.bwt) ===== */
@layer components {

.sh-hero {
  position: relative;
  margin-top: 0;
  min-height: 100vh;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  background: var(--sh-ink);
}
.sh-hero--no-img {
  background: var(--sh-ink);
  align-items: center;
}

/* Background image: fills entire section, behind header */
.sh-hero__bg {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
.sh-hero__bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  display: block;
}

/* Gradient: heavy at bottom for text legibility, fades to transparent top */
.sh-hero__overlay {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  background: linear-gradient(
    to top,
    rgba(26, 26, 24, 0.80) 0%,
    rgba(26, 26, 24, 0.50) 33%,
    rgba(26, 26, 24, 0.18) 60%,
    rgba(26, 26, 24, 0.03) 100%
  );
}
.sh-hero--no-img .sh-hero__overlay { display: none; }

/* Content: above overlay, anchored at bottom with padding */
.sh-hero__content {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  width: 100%;
  padding-top: 148px;   /* 72px header + 76px breathing room */
  padding-bottom: 88px;
}
.sh-hero--no-img .sh-hero__content {
  align-items: center;
  padding-bottom: 0;
}

/* Text column: left-anchored */
.sh-hero__text-col { max-width: 560px; }
.sh-hero--no-img .sh-hero__text-col {
  max-width: 640px;
  text-align: center;
  margin: 0 auto;
}

.sh-hero__eyebrow {
  display: block;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(247, 244, 239, 0.68);
  margin-bottom: 18px;
}

.sh-hero__title {
  font-family: var(--sh-serif);
  font-size: var(--fs-hero);
  font-weight: 300;
  line-height: 1.12;
  letter-spacing: 0.02em;
  color: var(--sh-ivory);
  margin-bottom: 40px;
}
.sh-hero__title em { font-style: italic; }

/* Right image column: ALWAYS hidden — bg image covers the full hero */
.sh-hero__img-col { display: none; }

/* CTA: outlined transparent button with sliding fill on hover */
.sh-hero__cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 28px;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--sh-ivory);
  background: transparent;
  border: 1px solid rgba(247, 244, 239, 0.55);
