  z-index: 0;
}
.sh-hero__cta:hover::before { transform: translateX(0); }
.sh-hero__cta:hover { border-color: var(--sh-ivory); }
.sh-hero__cta span,
.sh-hero__cta svg { position: relative; z-index: 1; }
.sh-hero__cta svg {
  flex-shrink: 0;
  transition: transform 0.3s ease-in-out;
}
.sh-hero__cta:hover svg { transform: translateX(4px); }

/* ═══════════════════════════════════════════════════════════════
