  font-family: var(--sh-serif);
  font-size: var(--fs-hero);
  font-weight: 300;
  line-height: 1.15;
  color: var(--sh-ivory);
  margin-bottom: 20px;
  letter-spacing: .02em;
}
.sh-editorial__title em { font-style: italic; }
.sh-editorial__desc {
  font-family: var(--sh-sans);
  font-size: var(--fs-xs);
  line-height: 1.7;
  color: rgba(247,244,239,.75);
  margin-bottom: 32px;
}
.sh-editorial__cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--sh-ivory);
  text-decoration: none;
  border-bottom: 1px solid rgba(247,244,239,.4);
  padding-bottom: 4px;
  transition: border-color 200ms, color 200ms;
}
.sh-editorial__cta:hover { border-color: var(--sh-ivory); color: var(--sh-ivory); }
.sh-editorial__cta svg { transition: transform 300ms; }
.sh-editorial__cta:hover svg { transform: translateX(4px); }

/* ═══════════════════════════════════════════════════════════════
   TREATMENT PROGRAMS
═══════════════════════════════════════════════════════════════ */
.sh-programs {
  padding: 88px 0;
  background: var(--sh-ivory);
  border-top: 1px solid var(--sh-line);
}
.sh-programs__hd {
  max-width: 560px;
  margin-bottom: 48px;
}
.sh-programs__intro {
  font-family: var(--sh-sans);
  font-size: var(--fs-sm);
  line-height: 1.75;
  color: var(--sh-ink-60);
  margin-top: 16px;
}

/* Numbered list */
.sh-programs__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--sh-line);
}
.sh-program-item {
  border-bottom: 1px solid var(--sh-line);
}
.sh-program-item__link {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 22px 0;
  text-decoration: none;
  color: var(--sh-ink);
  transition: color 200ms;
}
.sh-program-item__link:hover { color: var(--sh-gold); }
.sh-program-item__num {
  font-family: var(--sh-serif);
  font-size: var(--fs-sm);
  font-weight: 300;
  letter-spacing: .1em;
  color: var(--sh-ink-30);
  min-width: 28px;
  transition: color 200ms;
}
.sh-program-item__link:hover .sh-program-item__num { color: var(--sh-gold); }
.sh-program-item__name {
  font-family: var(--sh-serif);
  font-size: var(--fs-card);
  font-weight: 400;
  letter-spacing: .02em;
  flex: 1;
}
.sh-program-item__arrow {
  flex-shrink: 0;
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 250ms, transform 250ms;
  color: var(--sh-ink-60);
}
.sh-program-item__link:hover .sh-program-item__arrow {
  opacity: 1;
  transform: translateX(0);
}

/* CTA */
.sh-programs__cta {
  margin-top: 48px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.sh-programs__cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 32px;
  border: 1px solid var(--sh-ink);
  font-family: var(--sh-sans);
  font-size: var(--fs-3xs);
  font-weight: 500;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--sh-ink);
  text-decoration: none;
  transition: background 300ms, color 300ms, border-color 300ms;
}
.sh-programs__cta-btn:hover {
  background: var(--sh-ink);
  color: var(--sh-ivory);
}
.sh-programs__cta-btn svg { flex-shrink: 0; transition: transform 300ms; }
.sh-programs__cta-btn:hover svg { transform: translateX(4px); }
.sh-programs__cta-btn--outline {
  border-color: var(--sh-ink-30);
  color: var(--sh-ink-60);
}
.sh-programs__cta-btn--outline:hover {
  background: transparent;
  border-color: var(--sh-gold);
  color: var(--sh-gold);
}

/* ═══════════════════════════════════════════════════════════════
   RESPONSIVE — homepage sections, tablet breakpoint
═══════════════════════════════════════════════════════════════ */
@media (max-width: 991px) {
  .sh-concerns__grid { grid-template-columns: repeat(2, 1fr); }
  .sh-categories__grid { grid-template-columns: repeat(2, 1fr); }
  .sh-hero__title { font-size: var(--fs-hero); }
  .sh-editorial__title { font-size: var(--fs-2xl); }
}

@media (max-width: 767px) {
  .sh-hero { min-height: 88vh; }
  .sh-hero__overlay {
    background: linear-gradient(
      to top,
      rgba(26, 26, 24, 0.84) 0%,
      rgba(26, 26, 24, 0.48) 40%,
      rgba(26, 26, 24, 0.06) 80%,
      rgba(26, 26, 24, 0) 100%
    );
  }
  .sh-hero__title { font-size: var(--fs-2xl); }
  .sh-hero__content { padding-top: 100px; padding-bottom: 52px; }

  .sh-concerns { padding: 48px 0; }
  .sh-concerns__grid { grid-template-columns: repeat(2, 1fr); }

  .sh-categories { padding: 48px 0; }
  .sh-categories__grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }

  .sh-editorial { height: auto; padding: 72px 0; }
  .sh-editorial__title { font-size: var(--fs-h3); }

  .sh-programs { padding: 56px 0; }
  .sh-programs__intro { font-size: var(--fs-xs); }
  .sh-program-item__name { font-size: var(--fs-base); }
  .sh-program-item__link { gap: 16px; padding: 18px 0; }
  .sh-programs__cta { margin-top: 32px; }
}

@media (max-width: 480px) {
  .sh-concerns__grid { grid-template-columns: 1fr 1fr; }
  .sh-categories__grid { grid-template-columns: 1fr 1fr; }
}

}

/* ===== Most View App (chuyển từ assets/comp_most_view.scss.bwt) ===== */
@layer components {


/* ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   App block: Most Viewed Products (.ab-most-view-product-module)
   Restyle to match section_featured_products — cannot modify HTML
   ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */

/* 2026-10-06 (theme 1168609): khối nằm trong .pc-portal — reset cũ
   (home-portal.css, cùng độ ưu tiên, nạp sau) xoá padding nút/khung ⇒ nút còn 14px, thẻ dính mép. Bọc cả khối
   trong `body` để mọi rule hơn reset 1 bậc (0,x,1), không thêm cờ important. */
body {

  .ab-most-view-product-module .most-view-module {
    background-color: var(--bg-subtle) !important;
    /* 2026-10-13 (người dùng: "không lệch so với các section khác"): cùng nhịp dọc section trang chủ
       (home-portal.css `.pc-portal section{padding:78px 0}`, ≤680px 54px). */
    padding: 78px 0 68px; /* đáy 68 + 10px đệm dưới của hàng thẻ (app) = 78 */
    @media (max-width: 680px) { padding: 54px 0 44px; }
    overflow: hidden;
  }

  /* Container — áp cho heading + body vì không có .container div. Có .most-view-module trong selector để hơn
     rule app `.ab-most-view-product-module .most-view-module .most-view-module-body {padding:10px 0}` (0,3,0)
     — thiếu nó thì lề 16px không bao giờ ăn, thẻ/tiêu đề dính mép màn hình (1168609). */
  .ab-most-view-product-module .most-view-module .most-view-module-heading,
  .ab-most-view-product-module .most-view-module .most-view-module-body {

    max-width: var(--pc-container-max, 1280px);
    margin-left: auto !important;
    margin-right: auto !important;
    padding-left: var(--pc-container-gutter, 32px);
    padding-right: var(--pc-container-gutter, 32px);
  }

  /* Header: title trái — pager phải
     DOM order: pager trước, title sau → dùng order + position để override app CSS */
  .ab-most-view-product-module .most-view-module-heading {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 0;
    margin-bottom: 18px !important;
    position: relative;
  }
  .ab-most-view-product-module .most-view-module .most-view-module-title {
    order: 1;
    flex: 1;
    color: var(--mainColorDark) !important;
    font-size: var(--fs-xl) !important;
    font-weight: 700 !important;
    font-style: normal !important;
    font-family: var(--font-heading, var(--font-primary));
    text-align: left !important;
    text-transform: uppercase !important;
    margin: 0 !important;
    padding: 0 !important;
    float: none !important;
    position: static !important;
  }
  /* 2026-10-13 (người dùng): bỏ đường kẻ dưới tiêu đề (app: border-bottom #cacaca); 2 nút ‹ › chuyển xuống 2 bên hàng sản phẩm,
     giữa chiều cao thẻ (thân khối lệch tâm khối ~37px vì tiêu đề ở trên), nút tròn trắng không viền (app: box-shadow inset). */
  .ab-most-view-product-module .most-view-module .most-view-module-heading {
    border-bottom: 0 !important;
    position: static !important; /* nút bám theo cả khối .most-view-module, không theo tiêu đề */
    padding-top: 0 !important;    /* app: padding 10px 0 — bỏ để tiêu đề → thẻ = 40px như .section-head */
    padding-bottom: 0 !important;
    margin-bottom: 30px !important; /* + 10px đệm trên của hàng thẻ (app, chừa bóng thẻ khi hover) = 40px */
  }
  .ab-most-view-product-module .most-view-module .most-view-module-body {
    padding-top: 0 !important;
    padding-bottom: 0 !important;
  }
  .ab-most-view-product-module .most-view-module {
    position: relative;
  }
  .ab-most-view-product-module .most-view-module .most-view-module-heading .most-view-module-pager {
    position: absolute !important;
    z-index: 3;
    top: calc(50% + 37px);
    left: 50%;
    width: calc(min(var(--pc-container-max, 1280px), 100%) - 2 * var(--pc-container-gutter, 32px));
    transform: translate(-50%, -50%);
    display: flex !important;
    justify-content: space-between;
    padding: 0 !important;
    float: none !important;
    pointer-events: none;
  }
  .ab-most-view-product-module .most-view-module .most-view-btn-pager {
    pointer-events: auto;
    width: 40px;
    height: 40px;
    border: 0 !important;
    border-radius: 50% !important;
    background: #fff !important;
    box-shadow: 0 2px 10px rgba(0, 0, 0, .14) !important;
    color: var(--mainColorDark) !important;
    font-size: var(--fs-lg);
    font-weight: 700;
    line-height: 1;
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    margin: 0 !important;
    padding: 0 !important;
    transition: color .2s, background .2s, opacity .2s;
    &:hover, &:focus-visible {
      background: var(--mainColor) !important;
      color: #fff !important;
    }
    &.swiper-button-disabled {
      opacity: .35;
      cursor: default;
    }
  }
  /* Desktop: nút nằm đè nửa ra ngoài mép thẻ; màn nhỏ (khối tràn sát mép, overflow:hidden) giữ nút trong khung. */
  @media (min-width: 1340px) {
    .ab-most-view-product-module .most-view-module .most-view-btn-pager-prev { transform: translateX(-50%); }
    .ab-most-view-product-module .most-view-module .most-view-btn-pager-next { transform: translateX(50%); }
  }

  /* Product card */
  .ab-most-view-product-module .most-view-product-element {
    background: #fff;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--lineColor, #e8e8e8);
    display: flex !important;
    flex-direction: column;
    height: auto !important;
    transition: box-shadow .2s, transform .2s;
    &:hover {
      box-shadow: 0 8px 24px rgba(0,0,0,.1);
      transform: translateY(-2px);
    }
  }

  /* Image */
  /* Selector đủ dài để hơn rule app (0,5,0) `.ab-most-view-product-module .most-view-module
     .most-view-module-products-slide .most-view-product-element .most-view-product-img {height:260–330px}` —
     height cố định làm aspect-ratio bị bỏ qua, lộ dải nền xám dưới ảnh. */
  .ab-most-view-product-module .most-view-module .most-view-module-products-slide .most-view-product-element .most-view-product-img {
    aspect-ratio: 1 / 1;
    height: auto;
    padding: 0;
    overflow: hidden;
    background: #fff;
    flex-shrink: 0;
  }
  .ab-most-view-product-module .most-view-product-img img {
    width: 100%;
    height: 100%;
    /* ảnh sản phẩm nền trắng: contain để không cắt mất hộp/tuýp sản phẩm. */
    object-fit: contain;
    display: block;
    transition: transform .35s ease;
  }
  .ab-most-view-product-module .most-view-product-element:hover .most-view-product-img img {
    transform: scale(1.04);
  }

  /* Content area */
  .ab-most-view-product-module .most-view-product-element > a {
    display: flex;
    flex-direction: column;
    flex: 1;
    text-decoration: none;
    color: inherit;
  }
  .ab-most-view-product-module .most-view-product-content {
    padding: 12px 12px 0 !important;
    min-height: unset !important;
    height: auto !important;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .ab-most-view-product-module .most-view-product-name {
    max-height: unset !important;
    flex: 1;
  }
  .ab-most-view-product-module .most-view-product-name p {
    font-family: var(--font-primary);
    font-size: var(--fs-sm);
    font-weight: 700;
    color: var(--textColor, #333);
    line-height: 1.45;
    text-align: left;
    margin: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  /* Price */
  .ab-most-view-product-module .most-view-product-price {
    padding: 0 0 8px;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }
  .ab-most-view-product-module .most-view-product-price .money {
    color: var(--mainColor) !important;
    font-size: var(--fs-base);
    font-weight: 700;
  }
  .ab-most-view-product-module .most-view-product-oldprice {
    color: #999 !important;
    font-size: var(--fs-xs, 12px);
    font-weight: 400;
    text-decoration: line-through;
  }

  /* Action button */
  .ab-most-view-product-module .most-view-product-action {
    padding: 0 12px 12px;
  }
  .ab-most-view-product-module .most-view-product-to-cart {
    margin: 0;
  }
  .ab-most-view-product-module .most-view-btn-cart {
    display: flex !important;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 40px;
    /* vendor_appbulk.css đặt line-height: 12px cho .most-view-btn ⇒ chữ tràn khỏi nền. */
    line-height: 1.3;
    padding: 9px 12px;
    background: var(--mainColorDark) !important;
    color: #fff !important;
    border: none;
    border-radius: 8px;
    font-family: var(--font-primary);
    font-size: var(--fs-sm);
    font-weight: 600;
    text-align: center;
    text-decoration: none !important;
    cursor: pointer;
    transition: background .2s, transform .2s;
    &:hover {
      background: var(--mainColor) !important;
      transform: translateY(-1px);
    }
  }

}

}

