  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  width: 100%;
}

body.pc-home-v3 header.header.is-scrolled {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 1000 !important;
  animation: pc-header-slide-down 0.25s ease-out;
}

@keyframes pc-header-slide-down {
  from {
    transform: translateY(-20px);
