@media (max-width: 767px) {
  header.header :is(.card, .main-header) { background-color: #fff !important; padding-bottom: 0 !important; }
  header.header :is(.card-body, .box-hearder) { border-bottom: 1px solid #DCE5DF !important; box-shadow: 0 1px 3px rgba(0, 46, 35, 0.05) !important; }
  .pc-pdp-trust { margin: 12px 0 6px !important; }
  .pc-pdp-trust__list { grid-template-columns: repeat(3, 1fr) !important; gap: 8px !important; padding: 8px 6px !important; background: #F8FAF9 !important; border: 1px solid #EAEFEA !important; border-radius: 8px !important; margin: 0 !important; }
  .pc-pdp-trust__item { display: flex !important; flex-direction: row !important; align-items: center !important; justify-content: center !important; gap: 5px !important; padding: 2px !important; }
  .pc-pdp-trust__icon { width: 15px !important; height: 15px !important; flex-shrink: 0 !important; margin: 0 !important; }
  .pc-pdp-trust__text { min-width: 0 !important; }
  .pc-pdp-trust__text strong { font-size: var(--fs-xs, 12px) !important; line-height: 1.2 !important; font-weight: 600 !important; white-space: nowrap !important; }
  .pc-pdp-trust__desc { display: none !important; }
  .product-review-details { padding-left: 0 !important; padding-right: 0 !important; }
  .product-review-details .product-tab .tabs-title { padding-left: 0 !important; padding-right: 0 !important; margin-bottom: 12px !important; }
  .product-review-details .product-tab .tab-content { padding-left: 0 !important; padding-right: 0 !important; }
  .product-sidebar .product-favorite { padding-left: 0 !important; padding-right: 0 !important; }
}

.scrollbar-none,
.product-review-details .product-tab .tabs-title,
.product-tab .tabs-title,
.pc-pdp-articles__grid,
.js-viewed-list,
.swiper-wrapper,
.swiper-container {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}
.scrollbar-none::-webkit-scrollbar,
.product-review-details .product-tab .tabs-title::-webkit-scrollbar,
.product-tab .tabs-title::-webkit-scrollbar,
.pc-pdp-articles__grid::-webkit-scrollbar,
.js-viewed-list::-webkit-scrollbar,
.swiper-wrapper::-webkit-scrollbar,
.swiper-container::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}
@media (max-width: 575px) {
  .pc-pdp-articles__head {
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
  }
  .pc-pdp-articles__more {
    font-size: var(--fs-xs, 12px) !important;
  }
}

/* Unified layout-product and container gutter across PDP */
@media (max-width: 767px) {
  .layout-product > .container,
  .pc-pdp-articles > .container,
  .section-recenview-product > .container,
  .section_same_price .container {
    padding-left: var(--pc-container-gutter, 20px) !important;
    padding-right: var(--pc-container-gutter, 20px) !important;
  }
  .product-review-details .product-tab .tabs-title {
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
}

/* Fix PDP tab border and alignment */
.product-review-details .product-tab .tabs-title {
  display: flex !important;
  align-items: flex-end !important;
  border-bottom: 1px solid #dee2e6 !important;
  padding: 0 !important;
  margin-bottom: 20px !important;
  gap: 24px !important;
}
.product-review-details .product-tab .tab-link {
  cursor: pointer !important;
  padding: 8px 4px !important;
  margin: 0 !important;
  position: relative !important;
  border-bottom: 2px solid transparent !important;
  margin-bottom: -1px !important;
}
.product-review-details .product-tab .tab-link.active {
  border-bottom: 2px solid var(--mainColor, #3CB371) !important;
  color: var(--mainColor, #3CB371) !important;
}
.product-review-details .product-tab .tab-link h3 {
  margin: 0 !important;
  padding: 0 !important;
  font-size: var(--fs-md, 14px) !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.04em !important;
  line-height: 1.4 !important;
}
.product-review-details .product-tab .tab-link.active h3 {
  color: var(--mainColor, #3CB371) !important;
}
.product-review-details .product-tab .tab-link:not(.active) h3 {
  color: var(--color-text-muted, #64748B) !important;
}
.product-review-details .product-tab .pc-pdp-desc-fallback p {
  margin-bottom: 16px !important;
  line-height: 1.6 !important;
  color: var(--color-text-body, #334155) !important;
}
